#!/usr/bin/env python3
"""把 assets/*.mp3 转成 base64 内联表 fork/assets.js。

壳页面通过 file:// 加载时 fetch() 不可用（WKWebView / Chromium 皆然），
所以音频随页面以 base64 内联，运行时 atob → ArrayBuffer → decodeAudioData。
"""
import base64
import json
import pathlib
import sys


def main() -> None:
    src = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else "assets")
    out = pathlib.Path(sys.argv[2] if len(sys.argv) > 2 else "fork/assets.js")
    table = {}
    for f in sorted(src.glob("*.mp3")):
        table[f.stem] = base64.b64encode(f.read_bytes()).decode("ascii")
    js = (
        "/* generated by tools/embed_audio.py - do not edit */\n"
        "window.__CLAUDE_SPLASH_AUDIO__ = "
        + json.dumps(table, ensure_ascii=False)
        + ";\n"
    )
    out.write_text(js, encoding="utf-8")
    total = sum(len(v) for v in table.values())
    print(f"wrote {out} ({len(table)} files, {total} base64 chars)")


if __name__ == "__main__":
    main()
